008-7-scoping-and-name-resolution-exampl.code:
var x = 1
{
    var x = "hello"           // shadow：OK
    print(x)                 // "hello"
}
print(x)                     // 1

fn make_counter() -> (() -> i64) {
    var count = 0
    return fn() -> i64 {
        count += 1                  // 修改外层 count
        return count
    }
}

var c = make_counter()
print(c())      // 1
print(c())      // 2
